output_text:
[
  {
    "id": "no_carts_in_single_file_aisles",
    "text": "Shopping carts are prohibited in single-file shelf aisles where shelves flank both sides.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_enter_narrow_aisle_with_cart",
    "text": "Before entering a single-file shelf aisle, the customer must leave the cart outside rather than pushing it in.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "enterSingleFileShelfAisleWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileShelfAisleWithCart"
    }
  },
  {
    "id": "cartless_only_in_allowed_zones",
    "text": "Customers may be without their cart only at the entrance/cart station, at a cart-parking mouth, or inside a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "entranceOrCartStation": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "cartlessPermittedPlace": {
          "or": [
            "entranceOrCartStation",
            "cartParkingMouth",
            "singleFileShelfAisle"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          {
            "not": "cartlessPermittedPlace"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_parked_cart",
    "text": "Whenever a cart is parked at a shelf-aisle mouth, it must eventually be retrieved before leaving.",
    "abstraction": {
      "state_properties": {
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "parkCartAtMouth": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT",
              "cartParkingMouth"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCartAtMouth": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT",
              "cartParkingMouth"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCartAtMouth",
      "discharge": "retrieveCartAtMouth"
    }
  },
  {
    "id": "must_take_cart_from_station",
    "text": "A customer must take a cart from the cart station before proceeding with the shopping trip.",
    "abstraction": {
      "state_properties": {
        "cartStation": "at(1,7)"
      },
      "events": {
        "takeCartFromStation": {
          "pre": {
            "and": [
              "cartStation",
              "INTERACT",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "takeCartFromStation"
    }
  },
  {
    "id": "no_exit_without_cart",
    "text": "Customers are prohibited from leaving the supermarket without their cart.",
    "abstraction": {
      "state_properties": {
        "exitCell": "at(11,7)"
      },
      "events": {
        "leaveStore": {
          "pre": {
            "and": [
              "EXIT",
              "exitCell"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "leaveStore",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "one_way_no_westbound_travel",
    "text": "The store circulation pattern is one-way, so westbound travel is prohibited.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "westboundTravel": {
          "pre": "W",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "westboundTravel"
    }
  },
  {
    "id": "interact_only_at_service_locations",
    "text": "Interactions are allowed only at service locations: the cart station, a cart-parking mouth, or a cell adjacent to a shelf.",
    "abstraction": {
      "state_properties": {
        "cartStation": "at(1,7)",
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "shelfServiceSpot": "adjShelf",
        "serviceLocation": {
          "or": [
            "cartStation",
            "cartParkingMouth",
            "shelfServiceSpot"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          {
            "not": "serviceLocation"
          }
        ]
      }
    }
  }
]
